// Lookup by canonical suffix (our system's key). Built once at load.
export const VOCAB_BY_CANONICAL: Map<string, ImprovisorChordDef> = (() => {
  const m = new Map<string, ImprovisorChordDef>();
  for (const def of IMPROVISOR_VOCAB) {
    m.set(def.canonical, def);
    m.set(def.ivSuffix, def);  // also accept original IV suffix
    for (const alias of def.aliases) m.set(alias, def);
  }
  return m;
})();

/** Look up an IV chord def by chord type (e.g., 'maj9', 'm7b5', '7alt').
 *  Returns null if the type isn't in the vocab. */
export function lookupChordDef(chordType: string): ImprovisorChordDef | null {
  return VOCAB_BY_CANONICAL.get(chordType) ?? null;
}
